package com.hoverlag;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup("hoverlag")
public interface HoverLagConfig extends Config
{
	@ConfigItem(
		keyName = "showRing",
		name = "Show ring",
		description = "Draw a ring at the game's mouse position: red when a click now would miss what's under the cursor",
		position = 0
	)
	default boolean showRing()
	{
		return false;
	}

	@Range(min = 0, max = 10)
	@ConfigItem(
		keyName = "trailLength",
		name = "Dots",
		description = "How many of the game's recent mouse positions to show",
		position = 1
	)
	default int trailLength()
	{
		return 4;
	}
}

package com.hoverlag;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.RenderingHints;
import java.awt.Shape;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.Perspective;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Ring (optional): where the game thinks the mouse is; red when a left click right now would hit something
 * other than what is under the cursor (a walk with the cursor on an NPC, or an NPC the cursor is
 * no longer on), green otherwise. Dots: the last few positions the game picked up, one per 20ms
 * update, fading with age; red where a click would have been scuffed while the game was there.
 */
class HoverLagOverlay extends Overlay
{
	private static final Color IN_SYNC = new Color(0, 255, 0, 200);
	private static final Color SCUFFED = new Color(255, 0, 0, 230);
	private static final int RING = 6;

	private final HoverLagPlugin plugin;
	private final Client client;
	private final HoverLagConfig config;

	@Inject
	HoverLagOverlay(HoverLagPlugin plugin, Client client, HoverLagConfig config)
	{
		this.plugin = plugin;
		this.client = client;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		Point hit = plugin.hitPos;
		if (hit == null)
		{
			return null;
		}
		net.runelite.api.Point m = client.getMouseCanvasPosition();
		Point mouse = new Point(m.getX(), m.getY());

		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		boolean scuffed = scuffed(mouse);
		HoverLagPlugin.Dot newest = plugin.trail.peekLast();
		if (scuffed && newest != null)
		{
			newest.scuffed = true;
		}

		int i = 0;
		int n = plugin.trail.size();
		for (HoverLagPlugin.Dot d : plugin.trail)
		{
			int alpha = 40 + 140 * ++i / n;
			g.setColor(d.scuffed ? new Color(255, 0, 0, alpha) : new Color(255, 255, 255, alpha));
			g.fillOval(d.pos.x - 2, d.pos.y - 2, 4, 4);
		}

		if (config.showRing())
		{
			g.setColor(scuffed ? SCUFFED : IN_SYNC);
			g.setStroke(new BasicStroke(2f));
			g.drawOval(hit.x - RING, hit.y - RING, RING * 2, RING * 2);
		}
		return null;
	}

	// Overlays draw after the scene, so the menu now holds this frame's hover test: its top entry is
	// what a left click would do. Compare that with the NPCs under the live cursor.
	private boolean scuffed(Point mouse)
	{
		if (client.isMenuOpen())
		{
			return false;
		}
		MenuEntry[] entries = client.getMenu().getMenuEntries();
		if (entries.length == 0)
		{
			return false;
		}
		MenuEntry top = entries[entries.length - 1];
		NPC aimed = top.getNpc();
		if (aimed != null)
		{
			Shape box = clickbox(aimed);
			return box != null && !box.contains(mouse);
		}
		if (top.getType() == MenuAction.WALK)
		{
			for (NPC npc : client.getTopLevelWorldView().npcs())
			{
				// Dying NPCs keep their model but offer no options, so walking is right there.
				NPCComposition comp = npc.getTransformedComposition();
				if (comp == null || !comp.isInteractible() || npc.isDead())
				{
					continue;
				}
				Shape box = clickbox(npc);
				if (box != null && box.contains(mouse))
				{
					return true;
				}
			}
		}
		return false;
	}

	// The area the client hit-tests the NPC's model against: its bounding box for models that use
	// one, otherwise each face's screen bounds padded by a few pixels. Placed the way the client
	// places the NPC's convex hull.
	private Shape clickbox(NPC npc)
	{
		LocalPoint lp = npc.getLocalLocation();
		WorldView wv = npc.getWorldView();
		if (lp == null || wv == null)
		{
			return null;
		}
		int z = Perspective.getFootprintTileHeight(client, lp, wv.getPlane(), npc.getFootprintSize())
			- npc.getAnimationHeightOffset();
		return Perspective.getClickbox(client, wv, npc.getModel(), npc.getCurrentOrientation(), lp.getX(), lp.getY(), z);
	}
}

package com.hoverlag;

import com.google.inject.Provides;
import java.awt.Point;
import java.util.ArrayDeque;
import java.util.Deque;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.BeforeRender;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

/**
 * The client copies the mouse position into the game only once per 20ms cycle and hover-tests the
 * scene at that copy, so what a click lands on can be a cycle behind the cursor. This draws where
 * the game currently thinks the mouse is, next to the real cursor.
 *
 * The client re-adds "Walk here" every cycle with that cycle's mouse copy, so its params, read just
 * before a frame is drawn, are the (viewport-relative) position that frame hit-tests at.
 */
@PluginDescriptor(
	name = "Hover Lag",
	description = "Visually indicates scuffed clicks",
	tags = {"click", "hover", "mouse", "lag", "misclick"}
)
public class HoverLagPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private HoverLagOverlay overlay;

	@Inject
	private HoverLagConfig config;

	// Client thread only (written before each frame, read by the overlay while drawing it).
	// Canvas position the current frame hit-tests at, null when the mouse isn't over the scene.
	Point hitPos;
	// Game mouse positions, oldest first. Stepped once per game cycle: a cycle that moved adds a
	// dot, one that didn't drops the oldest, so a still mouse drains it completely.
	final Deque<Dot> trail = new ArrayDeque<>();
	private int lastCycle = -1;

	@Provides
	HoverLagConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(HoverLagConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		hitPos = null;
		trail.clear();
	}

	@Subscribe
	public void onBeforeRender(BeforeRender event)
	{
		Point walk = walkPos(client.getMenu().getMenuEntries());
		// Off the scene, or the mouse has left the window (the client then parks its copy off-screen).
		if (walk == null || !inViewport(walk) || !mouseOnCanvas())
		{
			hitPos = null;
			trail.clear();
			return;
		}

		Point prev = hitPos;
		hitPos = new Point(walk.x + client.getViewportXOffset(), walk.y + client.getViewportYOffset());

		// Frames drawn between cycles reuse the same mouse copy; only a new cycle can move it.
		int cycle = client.getGameCycle();
		if (cycle == lastCycle)
		{
			return;
		}
		lastCycle = cycle;
		if (!hitPos.equals(prev))
		{
			trail.addLast(new Dot(hitPos));
			while (trail.size() > config.trailLength())
			{
				trail.removeFirst();
			}
		}
		else
		{
			trail.pollFirst();
		}
	}

	static final class Dot
	{
		final Point pos;
		// Set by the overlay if a click would have been scuffed while this was the game's position.
		boolean scuffed;

		Dot(Point pos)
		{
			this.pos = pos;
		}
	}

	private boolean inViewport(Point viewport)
	{
		return viewport.x >= 0 && viewport.y >= 0
			&& viewport.x < client.getViewportWidth() && viewport.y < client.getViewportHeight();
	}

	private boolean mouseOnCanvas()
	{
		net.runelite.api.Point m = client.getMouseCanvasPosition();
		return m.getX() >= 0 && m.getY() >= 0 && m.getX() < client.getCanvasWidth() && m.getY() < client.getCanvasHeight();
	}

	private static Point walkPos(MenuEntry[] entries)
	{
		for (MenuEntry e : entries)
		{
			if (e.getType() == MenuAction.WALK)
			{
				return new Point(e.getParam0(), e.getParam1());
			}
		}
		return null;
	}
}

package com.hoverlag;

import java.util.ArrayList;
import java.util.List;
import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;
import net.runelite.client.plugins.Plugin;

public class HoverLagTest
{
	public static void main(String[] args) throws Exception
	{
		List<Class<? extends Plugin>> plugins = new ArrayList<>();
		plugins.add(HoverLagPlugin.class);
		// Comma-separated plugin classes compiled in alongside, e.g. by another project's dev launch.
		for (String name : System.getProperty("extraPlugins", "").split(","))
		{
			if (!name.isBlank())
			{
				plugins.add(Class.forName(name.trim()).asSubclass(Plugin.class));
			}
		}
		// loadBuiltin replaces its list on every call, so everything goes in one call.
		ExternalPluginManager.loadBuiltin(plugins.toArray(new Class[0]));
		RuneLite.main(args);
	}
}
